 {};                                    // model -> 'zero' | 'daily' (dlaczego go pomijamy)\nlet concCap = 99;                                         // ile zapytań naraz wolno (zmniejszane po limicie chwilowym)\nconst deadUntil = {};                                   // model -> do kiedy pomijamy (404/403/brak limitu)\n\nconst isDead = m => (deadUntil[m] || 0) > Date.now();\nconst markDead = (m, min = 15) => { deadUntil[m] = Date.now() + min * 60000; };\nfunction resetApiState() {                                // czysty start liczników i blokad „martwych” modeli\n  for (const k of Object.keys(deadUntil)) delete deadUntil[k];\n  for (const k of Object.keys(deadReason)) delete deadReason[k];\n  cooldownUntil = 0; concCap = 99;\n}\nfunction noteRequest(kind) {\n  USAGE.req++; USAGE[kind]++;\n  const n = Date.now(); USAGE.recent.push(n);\n  while (USAGE.recent.length && n - USAGE.recent[0] > 120000) USAGE.recent.shift();\n}\nfunction noteResult(res) {\n  if (res.ok) { USAGE.ok++; const u = res.json && res.json.usageMetadata; if (u && u.totalTokenCount) USAGE.tokens += u.totalTokenCount; }\n  else { if (res.status === 429) USAGE.e429++; else USAGE.err++; USAGE.lastErr = `HTTP ${res.status}: ${errMsg(res).slice(0, 600)}`; }\n  /* liczniki zużycia nie są pokazywane w interfejsie */\n}\n// Do północy czasu pacyficznego (wtedy odnawiają się dzienne limity API) – w minutach.\nfunction minutesToPacificMidnight() {\n  try {\n    const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', hour12: false, hour: '2-digit', minute: '2-digit' }).formatToParts(new Date());\n    const h = (+parts.find(p => p.type === 'hour').value) % 24, m = +parts.find(p => p.type === 'minute').value;\n    return 24 * 60 - (h * 60 + m);\n  } catch (e) { return 360; }\n}\n// Wyciąga z odpowiedzi 429 dokładną nazwę i wartość przekroczonego limitu (QuotaFailure) oraz czas oczekiwania.\nfunction parseQuota(res, model) {\n  const err = (res.json && res.json.error) || {}, msg = String(err.message || res.text || '');\n  const q = { model: model || null, id: '', metric: '', value: null, retryMs: retryDelayMs(res), msg, at: Date.now(), status: res.status, violations: [] };\n  for (const d of err.details || []) {\n    if (/QuotaFailure/.test(d['@type'] || '')) for (const v of d.violations || []) {\n      q.violations.push({ id: v.quotaId || '', metric: v.quotaMetric || '', value: v.quotaValue != null ? String(v.quotaValue) : null, model: (v.quotaDimensions && v.quotaDimensions.model) || null });\n    }\n  }\n  const pick = q.violations.find(v => v.value === '0') || q.violations[0];\n  if (pick) { q.id = pick.id; q.metric = pick.metric; q.value = pick.value; q.model = pick.model || q.model; }\n  let m;\n  if (q.value == null && (m = /limit:\\s*(\\d+)/i.exec(msg))) q.value = m[1];\n  if (!q.metric && (m = /metric:\\s*([\\w./\\-]+)/i.exec(msg))) q.metric = m[1];\n  if (!q.id && (m = /Quota ID:\\s*([\\w\\-]+)/i.exec(msg))) q.id = m[1];\n  if (!q.model && (m = /model:\\s*([\\w.\\-]+)/i.exec(msg))) q.model = m[1];\n  const blob = `${q.id} ${q.metric} ${msg}`;\n  q.zero = q.value === '0' || q.violations.some(v => v.value === '0') || /limit:\\s*0\\b/i.test(msg);\n  q.daily = /PerDay|per_day|per day/i.test(blob);\n  q.minute = /PerMinute|per_minute|per minute/i.test(blob);\n  q.free = /FreeTier|free_tier/i.test(blob);\n  q.spend = /spend/i.test(blob);\n  q.short = [q.model, q.id || q.metric || null, q.value != null ? `limit ${q.value}` : null].filter(Boolean).join(' · ') || 'API nie podało szczegółów';\n  return q;\n}\n// Po ludzku: co oznacza dany limit i co z nim zrobić.\nfunction explainQuota(q) {\n  const model = q.model ? ` (${q.model})` : '';\n  if (q.zero) return { level: 'bad', title: 'Limit 0 – brak przydziału, a nie wyczerpanie',\n    lines: [`Twoje konto Gemini nie ma w tej chwili przydziału na ten model${model}.`,\n      'Co zrobić: wybierz lżejszy model w kroku 04 (Nano Banana 2 zamiast Pro) albo spróbuj ponownie później.'], short: q.short };\n  if (q.daily) return { level: 'bad', title: 'Wyczerpany limit dzienny',\n    lines: [`Konto wyczerpało dzienny limit dla tego modelu${model}.`,\n      `Reset następuje o północy czasu pacyficznego — zostało około ${minutesToPacificMidnight()} min.`], short: q.short };\n  return { level: 'warn', title: 'Limit chwilowy',\n    lines: ['Za dużo zapytań naraz. Aplikacja sama zwalnia tempo i ponawia — zwykle wystarczy poczekać.',\n      'Możesz też zmniejszyć „Równoległe zapytania” w kroku 04.'], short: q.short };\n}\nfunction quotaFatal(chain) {\n  const isImg = chain.some(m => IMAGE_MODELS[m]), q = USAGE.lastQuota;\n  const zero = q && q.zero;\n  return fatal(isImg\n    ? (zero ? 'Twoje konto Gemini nie ma przydziału na modele obrazu. Wybierz lżejszy model w kroku 04 albo spróbuj później.'\n      : 'Modele obrazu odmówiły rysowania (limit). Aplikacja czekała i ponawiała — spróbuj ponownie za kilka minut.')\n    : 'Modele tekstowe odmówiły odpowiedzi (limit). Opowieści dni można wyłączyć w kroku 03.');\n}\n\n// Dowolny obraz z API -> JPEG (mniej pamięci niż PNG).\nasync function callGemini({ chain, bodiesFor, extract, signal, tag }) {\n  let lastErr = new Error('Brak odpowiedzi z API');\n  let blocked = 0;\n  const noQuotaLeft = () => chain.every(m => isDead(m) && (deadReason[m] === 'zero' || deadReason[m] === 'daily'));\n  if (noQuotaLeft()) throw quotaFatal(chain);                 // nie ma sensu pytać ponownie – od razu jasny komunikat\n  const alive = chain.filter(m => !isDead(m));\n  for (const model of (alive.length ? alive : chain)) {\n    const bodies = bodiesFor(model);\n    let dead = false;\n    for (let li = Math.min(levelMemo[model] || 0, bodies.length - 1); li < bodies.length && !dead; li++) {\n      let nextLevel = false;\n      for (let attempt = 0; attempt < 5 && !nextLevel && !dead; attempt++) {\n        if (signal && signal.aborted) throw abortErr();\n        let res;\n        try { res = await rawPost(model, bodies[li], signal); }\n        catch (e) {\n          if (e.name === 'AbortError') throw e;\n          lastErr = new Error('Błąd sieci: ' + e.message); log(`${tag}: ${lastErr.message}`, 'warn');\n          if (e.timeout && attempt >= 1) { dead = true; continue; }          // dwa zawieszone zapytania: próbujemy następnego modelu\n          await sleepAbortable(1500 * (attempt + 1), signal); continue;\n        }\n        if (res.ok) {\n          const out = extract(res.json);\n          if (out) { levelMemo[model] = li; return { value: out, model }; }\n          lastErr = new Error(emptyReason(res.json));\n          if (isBlocked(res.json) && ++blocked >= 2) { lastErr.blocked = true; throw lastErr; }\n          log(`${tag}: ${lastErr.message} (${model}, próba ${attempt + 1})`, 'warn');\n          await sleepAbortable(800 * (attempt + 1), signal); continue;\n        }\n        const msg = errMsg(res);\n        lastErr = new ApiError(`${model}: ${msg}`, res.status);\n        if (res.status === 400) {\n          if (/API key not valid|API_KEY_INVALID|API key expired/i.test(res.text)) {\n            throw fatal('Gemini Canvas nie przekazał zapytania do Twojego konta. Odśwież stronę Canvas i spróbuj ponownie.');\n          }\n          log(`${tag}: wariant żądania ${li + 1}/${bodies.length} odrzucony (400, ${model}) – to nieszkodliwe, próbuję następnego. Powód: ${msg.slice(0, 200)}`, 'warn');\n          nextLevel = true; continue;\n        }\n        if (res.status === 401 || res.status === 403 || res.status === 404) {\n          log(`${tag}: model ${model} niedostępny w tym środowisku (${res.status}) – próbuję następnego. ${msg.slice(0, 140)}`, 'warn');\n          markDead(model, res.status === 401 ? 5 : 15); dead = true; continue;\n        }\n        if (res.status === 429) {\n          const q = parseQuota(res, model); USAGE.lastQuota = q;\n          if (q.zero || q.daily) {                             // przydział zerowy albo dzienny: czekanie nic nie da – następny model\n            deadReason[model] = q.zero ? 'zero' : 'daily';\n            markDead(model, q.zero ? 60 : Math.min(minutesToPacificMidnight(), 360));\n            log(`${tag}: ${q.zero ? 'brak przydziału (limit: 0)' : 'limit dzienny wyczerpany'} – ${q.short}. Pomijam ten model.`, 'warn');\n            dead = true; continue;\n          }\n          const wait = Math.min(90000, q.retryMs || 4000 * 2 ** attempt);   // limit chwilowy: czekamy, ile każe API, i zwalniamy tempo\n          cooldownUntil = Math.max(cooldownUntil, Date.now() + wait);\n          if (concCap > 1) { concCap = 1; log('Limit chwilowy: zmniejszam liczbę równoległych zapytań do 1.', 'warn'); }\n          log(`${tag}: limit chwilowy (${q.short}) – czekam ${Math.round(wait / 1000)} s`, 'warn');\n          await sleepAbortable(wait, signal); continue;\n        }\n        if (res.status >= 500) {\n          log(`${tag}: błąd serwera ${res.status}, ponawiam`, 'warn');\n          await sleepAbortable(2000 * 2 ** Math.min(attempt, 3), signal); continue;\n        }\n        dead = true;\n      }\n      if (!nextLevel) dead = true;                    // wyczerpano próby dla tego modelu\n    }\n  }\n  if (noQuotaLeft()) throw quotaFatal(chain);\n  if (lastErr.status === 401) throw fatal('Żaden model nie odpowiedział — Canvas nie przekazał zapytań do Twojego konta (401). Odśwież stronę Canvas i uruchom aplikację ponownie.');\n  throw lastErr;\n}\n\nasync function genImage({ parts, ratio, size, S, signal, tag }) {\n  const chain = S.autoFallback ? [S.imageModel, ...IMAGE_ORDER.filter(m => m !== S.imageModel)] : [S.imageModel];\n  const r = await callGemini({ chain, signal, tag, bodiesFor: m => imageBodies(m, parts, ratio, size, S), extract: extractImage });\n  return { b64: r.value.data, mime: r.value.mime, model: r.model };\n}\nasync function genText({ parts, signal, tag }) {\n  const r = await callGemini({ chain: TEXT_MODELS, signal, tag, bodiesFor: () => [{ contents: [{ role: 'user', parts }] }], extract: extractText });\n  return r.value;\n}\n// Dowolny obraz z API -> JPEG (mniej pamięci niż PNG).\nasync function normalizeToJpeg(b64, mime, q = 0.92) {\n  const bmp = await createImageBitmap(b64ToBlob(b64, mime));\n  const c = canvasOf(bmp.width, bmp.height); c.getContext('2d').drawImage(bmp, 0, 0);\n  if (bmp.close) bmp.close();\n  return toBlob(c, 'image/jpeg', q);\n}\n\n/* ===================== 5. MOTYWY I PROMPTY ===================== */\n// Motyw dla danego dnia: „Karpacz, dzień 2 - basen” -> osobny klimat dla dnia 2.\nfunction themeForDay(S, dayIdx) {\n  if (S.category !== 'custom') return S.category;\n  const raw = S.customTheme;\n  if (!raw) return 'Dowolny kreatywny motyw w stylu Pixar';\n  let specific = null; const general = [];\n  for (const part of raw.split(',').map(p => p.trim()).filter(Boolean)) {\n    const m = part.match(/dzie[ńn]\\s*(\\d+)/i);\n    if (m) { if (parseInt(m[1], 10) === dayIdx) specific = part.replace(/[-:]?\\s*dzie[ńn]\\s*\\d+\\s*[-:]?/i, '').trim(); }\n    else general.push(part);\n  }\n  if (specific) return specific;\n  return general.length ? general.join(', ') : raw;\n}\nfunction subjectPool(S) {\n  const cat = S.category;\n  if (cat === '1. ZOO') return [...ANIMALS_DATA['1. ZOO']];\n  return [...(IMMERSIVE_DATA[cat] || IMMERSIVE_DATA.custom), ...(ANIMALS_DATA[cat] || ANIMALS_DATA.custom)];\n}\nfunction interactionRule(theme, subject) {\n  if (theme === '1. ZOO') return 'SCENA ZOO (100% Zwierzęta): Głównym interaktywnym bohaterem trzymającym zdjęcie jest wybrane zwierzę.';\n  if (String(subject).includes('INTERNET')) return 'INTERNET SEARCH RULE: Przeanalizuj podany motyw. Użyj wiedzy o świecie by wyszukać charakterystyczne obiekty, budowle (np. Śnieżka dla Karpacza), rzeźby lub lokalną faunę. Ten wyszukany element MUSI FIZYCZNIE TRZYMAĆ, OBEJMOWAĆ LUB TWORZYĆ RAMKĘ DLA ZDJĘCIA.';\n  return 'OBOWIĄZKOWA ZASADA DLA OBIEKTÓW ARCHITEKTONICZNYCH/NATURY: Zwracaj bezwzględną uwagę na logikę pory roku, klimatu i otoczenia narzuconą przez główny motyw. Wylosowany poniżej obiekt MUSI FIZYCZNIE TRZYMAĆ, OBEJMOWAĆ LUB TWORZYĆ RAMKĘ DLA ZDJĘCIA.';\n}\nconst CUSTOM_FRAME_RULE = 'ZASADA DLA RAMKI DOWOLNEJ: Zamiast zwykłej prostokątnej ramki, stwórz RAMKĘ JAKO CZĘŚĆ PRAWDZIWEJ SCENY. BARDZO WAŻNE: Wylosowany obiekt ma być JEDNOCZEŚNIE elementem trzymającym.';\n\n// Tryb bezpieczny: model dostaje szablon z magentowym oknem i dorysowuje tylko otoczenie.\nfunction promptSafe(o) {\n  return `SZABLON UKŁADU (dołączony obraz): biała płachta z jednym prostokątem w kolorze magenta #FF00FF. Prostokąt to okno na zdjęcie, które zostanie wstawione osobno, już po wygenerowaniu obrazu.\n\nZADANIE: zachowaj szablon i dorysuj wokół okna kompletną, efektowną ramkę-scenę zgodną z motywem poniżej.\n\nZASADY NIENARUSZALNE (OKNO):\n1. Prostokąt magenta zostaje dokładnie w tym samym miejscu, w tym samym rozmiarze i w tych samych proporcjach. Nie przesuwaj go, nie skaluj, nie obracaj, nie zaokrąglaj rogów.\n2. Wnętrze prostokąta pozostaje w 100% jednolitym, płaskim kolorem #FF00FF: bez cieni, gradientów, odblasków, tekstur i jakichkolwiek elementów. Nic (łapa, liść, ramię, cień, napis) nie wchodzi na okno. Elementy sceny mogą je tylko otaczać i dotykać jego krawędzi z zewnątrz.\n3. Kolor magenta / fuksja / neonowy róż nie występuje nigdzie indziej na obrazie.\n\nKOMPOZYCJA:\n- Okno jest fizyczną częścią sceny (otwór w ramie, portal, okno, kadr trzymany lub obejmowany przez obiekt).\n- Obiekt trzymający lub tworzący ramkę: ${o.subject}\n- Pozycja obiektu względem okna: ${o.pose}\n- ${o.interaction}\n- ${o.frameRule}\n- Wykorzystaj całą wolną przestrzeń wokół okna. Obiekt ma być duży, wyraźny i sięgać krawędzi okna.\n\nSTYL OBOWIĄZKOWY: Pixar 3D, film animowany, najwyższa jakość, ultra realistyczne materiały, fotorealistyczne tekstury, miękkie światło, global illumination.\nKLIMAT / MOTYW SCENY: ${o.theme}\nPOZA SCENĄ: czyste białe tło (#FFFFFF). Brak napisów, logo i znaków wodnych. Efekt gotowy do profesjonalnego druku.`;\n}\n// Tryb pełne AI: prompt z działającej wersji (model dostaje zdjęcie i sam je wkomponowuje).\nfunction promptFull(o) {\n  return `GŁÓWNA ZASADA (NIE ZMIENIAJ)\nWczytane zdjęcie jest NAJWAŻNIEJSZYM elementem kompozycji.\nNigdy nie zmieniaj twarzy. Nigdy nie zmieniaj sylwetki. Nigdy nie zmieniaj wieku. Nigdy nie zmieniaj proporcji ciała.\nNigdy nie kadruj zdjęcia. Nigdy nie ucinaj głowy. Nigdy nie ucinaj nóg. Nigdy nie zasłaniaj twarzy.\nZdjęcie musi być widoczne w 100%. Całe zdjęcie pozostaje ostre.\nAI tworzy jedynie otoczenie. Elementy grafiki mogą przechodzić przed zdjęciem i za zdjęciem tworząc efekt 3D.\n\nNOWA ZASADA OBOWIĄZKOWA (PRZEZROCZYSTOŚĆ):\nJeśli jakikolwiek wygenerowany element graficzny (np. łapa, liść, cień) nachodzi bezpośrednio na powierzchnię wgranego zdjęcia, uczyń ten fragment półprzezroczystym (efekt przezroczystego szkła, opacity), tak aby oryginalne zdjęcie pod spodem było całkowicie czytelne i wyraźne przez tę grafikę.\n\nSTYL OBOWIĄZKOWY\nPixar 3D, Film animowany, Najwyższa jakość, Ultra realistic materials, Photorealistic textures, Soft Lighting, Global Illumination.\n\nWYBRANA KATEGORIA / KLIMAT SCENY: ${o.theme}\n${o.interaction}\n\nGŁÓWNA POSTAĆ / OBIEKT TRZYMAJĄCY: ${o.subject}\nPOZYCJA OBIEKTU WZGLĘDEM ZDJĘCIA: ${o.pose}\n\n${o.frameRule}\nBiałe tło. Brak napisów. Brak logo. Brak znaków wodnych. Efekt gotowy do profesjonalnego wydruku 600 DPI.`;\n}\nfunction buildFramePrompt(S, theme, subject, pose) {\n  const custom = S.category === 'custom';\n  const frameRule = custom ? CUSTOM_FRAME_RULE\n    : (S.frameMode === 'safe' ? 'Okno otacza cienka, biała, drewniana ramka z białym matem, trzymana lub obejmowana przez obiekt.' : 'Umieść zdjęcie w białej drewnianej ramce. Ramka ma być cienka, biały mat.');\n  const o = { theme, subject, pose, interaction: interactionRule(theme, subject), frameRule };\n  return S.frameMode === 'safe' ? promptSafe(o) : promptFull(o);\n}\n// Podgląd promptu w panelu (z symbolami zastępczymi tam, gdzie losujemy).\nfunction promptPreview(S) {\n  const theme = S.category === 'custom' ? (S.customTheme || '[WPISZ WŁASNY MOTYW]') : S.category;\n  const subject = S.animal === 'random' ? '[AI LOSUJE POSTAĆ/OBIEKT BEZ POWTÓREK]'\n    : S.animal === 'internet' ? '[INTERNET: AI WYSZUKUJE ZGODNIE Z WŁASNYM MOTYWEM]' : $('#animal').selectedOptions[0]?.text || S.animal;\n  const pose = S.pose === 'random' ? '[AI LOSUJE POZYCJĘ BEZ POWTÓREK]' : $('#pose').selectedOptions[0]?.text || S.pose;\n  return buildFramePrompt(S, theme, subject, pose);\n}\n\n/* ---------- opowieści, okładki, znaczniki godzin ---------- */\nfunction storyPrompt(day, S, sample) {\n  const title = S.storyTitle\n    ? `Tytuł/Główny wątek narzucony przez użytkownika: \"${S.storyTitle}\". Bezwzględnie uwzględnij ten motyw w opowieści i zbuduj wokół niego historię. ZASADA JĘZYKA POLSKIEGO: Odmieniaj tytuł i nazwy przez przypadki, aby zachować poprawną stylistykę i gramatykę w całym opowiadaniu.`\n    : 'Brak narzuconego tytułu (opieraj się wyłącznie na zdjęciach i wybranym stylu).';\n  const themeName = String(day.theme || '').replace(/^\\d+\\.\\s*/, '');\n  const theme = themeName && themeName !== 'Dowolny kreatywny motyw w stylu Pixar'\n    ? `\\nKlimat, miejsce i motyw na TEN KONKRETNY DZIEŃ: \"${themeName}\". Bezwzględnie wpleć ten klimat, porę roku, lokację i porę dnia do wydarzeń w historii, odróżniając ten dzień od innych!` : '';\n  const times = sample.map((p, i) => p.timeStr ? `Zdjęcie ${i + 1}: ${p.timeStr}` : '').filter(Boolean).join(', ');\n  const timesText = times ? `Oto zarejestrowane godziny dla niektórych zdjęć: ${times}. Użyj ich naturalnie w historii (np. \"o 14:30 udaliśmy się...\").` : '';\n  return `Przeanalizuj dołączone fotografie z jednego dnia i stwórz piękną, krótką opowieść.\nDzień: ${fmtDate(day.key)} (Dzień ${day.index})\nBohaterowie: ${S.heroes}\nZASADA DLA BOHATERÓW: Używaj myślnika '-' jako detektywistycznej podpowiedzi kogo szukać na zdjęciach. Wszystko za myślnikiem to określenie wyglądu/roli. AI ma obowiązek przeanalizować twarze i ubiór osób ze zdjęć pasujących do opisu by rozpoznać kto jest kim. W samej ostatecznej napisanej opowieści UŻYWAJ JEDYNIE IMION (sprzed myślnika), z pełną odmianą przez przypadki (np. \"Poszliśmy z Arturem\").\nStyl opowieści: ${S.storyStyle}\n${title}${theme}\n${timesText}\n\nWYTYCZNE:\nZwróć uwagę na miejsca, zwierzęta, aktywność, pogodę widoczną na zdjęciach. Ułóż to w spójną historię zgodnie z chronologią wydarzeń. NIE zmyślaj bardzo konkretnych faktów, których nie można rozsądnie wywnioskować. Zakończ całą historię tego dnia w 3-4 zwięzłych akapitach, tworząc logiczną całość, tak by nigdy nie była nienaturalnie urwana. Cała opowieść ma mieć najwyżej ok. ${S.storyPages * 520} znaków. Pamiętaj o doskonałej stylistyce i ortografii języka polskiego.\nOd razu przejdź do treści historii, bez żadnych nagłówków.`;\n}\nfunction coverPrompt(chunk, S, ratio, hasRef) {\n  const ref = hasRef ? `\nBARDZO WAŻNE DOTYCZĄCE ZDJĘCIA REFERENCYJNEGO I POSTACI:\n1. Na dołączonym zdjęciu referencyjnym znajdują się twarze postaci podpisane imionami. ODCZYTAJ te imiona.\n2. Z podanej ogólnej puli bohaterów [${S.heroes}] na wygenerowanym obrazku umieść TYLKO I WYŁĄCZNIE te postaci, które faktycznie WYSTĘPUJĄ W PONIŻSZEJ HISTORII z tego dnia. Jeśli historia opowiada np. tylko o 2 osobach, wygeneruj tylko je, ignorując resztę osób z puli.\n3. TWARZE SĄ NIETYKALNE: Wygeneruj twarze zidentyfikowanych postaci w proporcji 1:1 w stosunku do zdjęcia referencyjnego. Twarze mają być w 100% takie same jak na zdjęciu (stałe twarze), dodaj im jedynie uśmiech.\n4. DODAJESZ TYLKO TUŁÓW I UBRANIE: Do stałych twarzy dodajesz tylko tułów z ubraniem. Każdego dnia postaci MUSZĄ MIEĆ INNE UBRANIA dopasowane idealnie do opisu wydarzeń danego dnia, zachowując spójny styl grafiki.\n5. POSTACI DODATKOWE (W TYM ZWIERZĘTA): Jeśli na liście bohaterów znajdują się dodatkowe postacie/zwierzęta, wygeneruj je w tej scenie ściśle według ich opisu, utrzymując piękno kompozycji.`\n    : `\nBARDZO WAŻNE DOTYCZĄCE POSTACI: Z podanej ogólnej puli bohaterów [${S.heroes}] na wygenerowanym obrazku umieść TYLKO te postaci, które faktycznie występują w poniższej historii z danego dnia. Ściśle trzymaj się ich opisów i zachowaj spójny styl grafiki.`;\n  const orient = ratioVal(ratio) >= 1 ? 'poziomą' : 'pionową';\n  return `Na podstawie poniższej krótkiej historii, wygeneruj JEDNĄ przepiękną, ${orient} ilustrację w proporcjach ${ratio}, która najlepiej podsumowuje wydarzenia i klimat tego dnia.\nSTYL OBRAZU: Pixar 3D, Film animowany, Najwyższa jakość, Ultra realistic, Cinematic Composition. Klimat dopasowany do: ${S.storyStyle}.\n${ref}\nHISTORIA DO ZILUSTROWANIA:\n${chunk}\nWymagania: Brak tekstu na obrazku. Skup się na pięknym krajobrazie i głównym wydarzeniu. Białe tło nie jest wymagane, obraz ma wypełniać cały kadr.`;\n}\nfunction stampPrompt(timeStr, theme) {\n  return `Wygeneruj uroczy, mały element dekoracyjny w stylu Pixar 3D (ZAKAZ ZEGARA ZE WSKAZÓWKAMI).\nWymagania:\n1. Obiekt lub postać pasująca do motywu: ${theme} (np. mały zwierzak, kamień, muszla).\n2. Ten uroczy obiekt/postać musi OBU RĘKAMI TRZYMAĆ LUB PREZENTOWAĆ płaską, drewnianą lub kamienną TABLICZKĘ (szyld).\n3. Na tej tabliczce wyryty jest bardzo wyraźny, duży tekst z godziną: \"${timeStr}\".\n4. ZAKAZ RYSOWANIA TRADYCYJNYCH TARCZ ZEGARA. To ma być po prostu postać trzymająca ładny napis z godziną.\n5. Białe tło. Styl: Pixar 3D, urocze, pastelowe, najwyższa jakość.`;\n}\n\n\n/* ===================== 6. RAMKI ===================== */\nfunction rrectPath(g, x, y, w, h, r) {\n  r = Math.max(0, Math.min(r, w / 2, h / 2));\n  g.beginPath(); g.moveTo(x + r, y);\n  g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);\n  g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();\n}\n// Geometria „okna” w kadrze: proporcje zdjęcia, środek nieco poniżej połowy (miejsce na głowę postaci).\nfunction templateGeom(ratio, photoAspect, pct, LONG) {\n  const R = ratioVal(ratio);\n  const W = R >= 1 ? LONG : Math.round(LONG * R), H = R >= 1 ? Math.round(LONG / R) : LONG;\n  let ww = W * pct, wh = ww / photoAspect;\n  if (wh > H * pct) { wh = H * pct; ww = wh * photoAspect; }\n  return { W, H, x: (W - ww) / 2, y: H * 0.53 - wh / 2, w: ww, h: wh };\n}\n// Szablon wysyłany do modelu: biała płachta + magentowe okno. Twoje zdjęcie NIE opuszcza urządzenia.\nfunction makeTemplate(ratio, photoAspect, pct) {\n  const t = templateGeom(ratio, photoAspect, pct, 1024);\n  const c = canvasOf(t.W, t.H), g = c.getContext('2d');\n  g.fillStyle = '#ffffff'; g.fillRect(0, 0, t.W, t.H);\n  g.fillStyle = '#ff00ff'; g.fillRect(Math.round(t.x), Math.round(t.y), Math.round(t.w), Math.round(t.h));\n  return c.toDataURL('image/png').split(',')[1];\n}\n\n// Znajduje magentowe okno w obrazie z AI i buduje maskę (bez obwódki na krawędziach).\nfunction detectWindow(img, photoAspect) {\n  const iw = img.width, ih = img.height, sc = Math.min(1, 640 / Math.max(iw, ih));\n  const w = Math.max(16, Math.round(iw * sc)), h = Math.max(16, Math.round(ih * sc)), N = w * h;\n  const c = canvasOf(w, h), g = c.getContext('2d', { willReadFrequently: true });\n  g.drawImage(img, 0, 0, w, h);\n  const d = g.getImageData(0, 0, w, h).data;\n  const key = new Uint8Array(N), loose = new Uint8Array(N);\n  for (let p = 0, i = 0; p < N; p++, i += 4) {\n    const r = d[i], gg = d[i + 1], b = d[i + 2];\n    if (r > 165 && b > 165 && gg < 120 && r - gg > 85 && b - gg > 85) key[p] = 1;                 // czysta magenta\n    if (r - gg > 40 && b - gg > 40 && Math.abs(r - b) < 110) loose[p] = 1;                        // jej cieniowane odcienie\n  }\n  const lab = new Int32Array(N), st = new Int32Array(N);\n  let bestArea = 0, bestId = 0, id = 0;\n  for (let s = 0; s < N; s++) {                                                                  // największa spójna plama\n    if (!key[s] || lab[s]) continue;\n    id++; let sp = 0, area = 0; st[sp++] = s; lab[s] = id;\n    while (sp) {\n      const p = st[--sp]; area++; const x = p % w;\n      if (x > 0 && key[p - 1] && !lab[p - 1]) { lab[p - 1] = id; st[sp++] = p - 1; }\n      if (x < w - 1 && key[p + 1] && !lab[p + 1]) { lab[p + 1] = id; st[sp++] = p + 1; }\n      if (p >= w && key[p - w] && !lab[p - w]) { lab[p - w] = id; st[sp++] = p - w; }\n      if (p < N - w && key[p + w] && !lab[p + w]) { lab[p + w] = id; st[sp++] = p + w; }\n    }\n    if (area > bestArea) { bestArea = area; bestId = id; }\n  }\n  if (!bestId || bestArea < N * 0.03) return { ok: false, why: 'nie znaleziono okna magenta' };\n  let x0 = w, y0 = h, x1 = -1, y1 = -1;\n  for (let p = 0; p < N; p++) if (lab[p] === bestId) { const x = p % w, y = (p / w) | 0; if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }\n  const bw = x1 - x0 + 1, bh = y1 - y0 + 1, fill = bestArea / (bw * bh);\n  if (fill < 0.7) return { ok: false, why: `okno ma nieregularny kształt (${Math.round(fill * 100)}%)` };\n  if (Math.abs(Math.log((bw / bh) / photoAspect)) > 0.3) return { ok: false, why: 'okno zmieniło proporcje' };\n  const M = new Uint8Array(N);\n  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) { const p = y * w + x; if (lab[p] === bestId || loose[p]) M[p] = 1; }\n  const R = 2, tmp = new Uint8Array(N), out = new Uint8Array(N);                                 // poszerzenie maski o 2 px\n  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { let v = 0; for (let k = Math.max(0, x - R); k <= Math.min(w - 1, x + R); k++) if (M[y * w + k]) { v = 1; break; } tmp[y * w + x] = v; }\n  for (let x = 0; x < w; x++) for (let y = 0; y < h; y++) { let v = 0; for (let k = Math.max(0, y - R); k <= Math.min(h - 1, y + R); k++) if (tmp[k * w + x]) { v = 1; break; } out[y * w + x] = v; }\n  const mc = canvasOf(w, h), mg = mc.getContext('2d'), md = mg.createImageData(w, h);\n  for (let p = 0; p < N; p++) md.data[p * 4 + 3] = out[p] ? 255 : 0;\n  mg.putImageData(md, 0, 0);\n  const sx = iw / w, sy = ih / h;\n  return { ok: true, mask: mc, dil: R, sx, sy, fill, bbox: { x: x0 * sx, y: y0 * sy, w: bw * sx, h: bh * sy } };\n}\n\n// Limity pamięci przy składaniu ramki (dłuższy bok / liczba pikseli). Słabsze urządzenia dostają niższy sufit.\nconst COMPOSE_MAX_LONG = 8192;\nconst composeMaxArea = () => (navigator.deviceMemory && navigator.deviceMemory < 6) ? 20e6 : 32e6;\nconst downSize = sz => ({ '4K': '2K', '2K': '1K' }[sz] || sz);\n// Składanie ramek jedna po drugiej: duże płótna nie kumulują się w pamięci nawet przy kilku zapytaniach naraz.\nlet composeChain = Promise.resolve();\nconst oneAtATime = fn => { const run = composeChain.then(fn, fn); composeChain = run.catch(() => { }); return run; };\n// Mała miniatura (kafelki „ściany”, lista) – żeby przeglądarka nie dekodowała wielomegapikselowych obrazów dla ikonki.\nasync function canvasThumbBlob(src, max = 360, q = 0.8) {\n  const sc = Math.min(1, max / Math.max(src.width, src.height));\n  const c = canvasOf(src.width * sc, src.height * sc), g = c.getContext('2d');\n  g.imageSmoothingQuality = 'high'; g.drawImage(src, 0, 0, c.width, c.height);\n  const b = await toBlob(c, 'image/jpeg', q); c.width = c.height = 1; return b;\n}\nasync function thumbOfBlob(blob, max = 360) {\n  const bmp = await decodeScaled(blob, max);\n  try { return await canvasThumbBlob(bmp, max); } finally { if (bmp.close) bmp.close(); }\n}\n\n// Wstawia ORYGINALNE zdjęcie w okno. Twarze pozostają 1:1, a zdjęcie zachowuje NATYWNĄ rozdzielczość:\n// ramkę z AI powiększamy tak, by okno pomieściło wszystkie piksele zdjęcia (w granicach pamięci urządzenia).\nasync function composeSafe(photo, raw, det) {\n  const W = raw.width, H = raw.height, bb = det.bbox;\n  const ph = await decodeBitmap(photo.file);\n  let out = null, layer = null;\n  try {\n    const sMin = Math.max(W, H) >= 1800 ? 1 : 2;\n    const sNative = Math.max(ph.width / bb.w, ph.height / bb.h);\n    const sCap = Math.max(1, Math.min(COMPOSE_MAX_LONG / Math.max(W, H), Math.sqrt(composeMaxArea() / (W * H))));\n    const S = Math.min(Math.max(sMin, sNative), sCap), OW = Math.round(W * S), OH = Math.round(H * S);\n    out = canvasOf(OW, OH); const o = out.getContext('2d');\n    o.imageSmoothingQuality = 'high'; o.drawImage(raw, 0, 0, OW, OH);\n    const pad = Math.ceil(det.dil * Math.max(det.sx, det.sy) * S) + 1;\n    const x0 = Math.max(0, Math.floor(bb.x * S - pad)), y0 = Math.max(0, Math.floor(bb.y * S - pad));\n    const x1 = Math.min(OW, Math.ceil((bb.x + bb.w) * S + pad)), y1 = Math.min(OH, Math.ceil((bb.y + bb.h) * S + pad));\n    const bw = x1 - x0, bh = y1 - y0;\n    layer = canvasOf(bw, bh); const l = layer.getContext('2d');           // warstwa tylko w obrębie okna (mniej pamięci)\n    l.imageSmoothingQuality = 'high';\n    l.fillStyle = '#ffffff'; l.fillRect(0, 0, bw, bh);\n    const mode = Math.abs(Math.log((ph.width / ph.height) / (bw / bh))) < 0.045 ? 'cover' : 'contain';\n    const r = fitInto(ph.width, ph.height, 0, 0, bw, bh, mode);\n    l.drawImage(ph, r.x, r.y, r.w, r.h);\n    if (det.fill < 0.985) {                                               // okno nieprostokątne: zachowujemy elementy sceny nachodzące na okno\n      const mw = det.mask.width, mh = det.mask.height;\n      l.globalCompositeOperation = 'destination-in';\n      l.drawImage(det.mask, x0 / OW * mw, y0 / OH * mh, bw / OW * mw, bh / OH * mh, 0, 0, bw, bh);\n    }\n    o.drawImage(layer, x0, y0);\n    const blob = await toBlob(out, 'image/jpeg', 0.93), thumb = await canvasThumbBlob(out);\n    return { blob, thumb, w: OW, h: OH };\n  } finally {\n    if (ph.close) ph.close();\n    if (out) out.width = out.height = 1;\n    if (layer) layer.width = layer.height = 1;\n  }\n}\nasync function packFull(raw) {\n  const c = canvasOf(raw.width, raw.height); c.getContext('2d').drawImage(raw, 0, 0);\n  try { return { blob: await toBlob(c, 'image/jpeg', 0.94), thumb: await canvasThumbBlob(c), w: raw.width, h: raw.height }; }\n  finally { c.width = c.height = 1; }\n}\n// Ramka lokalna (bez AI): zapas, gdy generowanie się nie uda – strona nigdy nie zostaje pusta.\nasync function makeLocalFrame(photo, S) {\n  let LONG = 2048; const t0 = templateGeom(photo.ratio, photo.aspect, S.windowPct, LONG);\n  LONG = clamp(Math.round(LONG * Math.max(photo.w / t0.w, photo.h / t0.h)), 2048, COMPOSE_MAX_LONG);\n  let t = templateGeom(photo.ratio, photo.aspect, S.windowPct, LONG);\n  while (t.W * t.H > composeMaxArea() && LONG > 2048) { LONG = Math.round(LONG * 0.92); t = templateGeom(photo.ratio, photo.aspect, S.windowPct, LONG); }\n  const c = canvasOf(t.W, t.H), g = c.getContext('2d'), u = t.W / 2048;      // u: skala względem układu 2048 px\n  g.fillStyle = '#ffffff'; g.fillRect(0, 0, t.W, t.H);\n  const meta = THEME_META[S.category] || THEME_META.custom, pad = Math.round(Math.min(t.W, t.H) * 0.035);\n  g.save(); g.shadowColor = 'rgba(0,0,0,.28)'; g.shadowBlur = t.W * 0.02; g.shadowOffsetY = t.W * 0.008;\n  g.fillStyle = meta.c; rrectPath(g, t.x - pad * 1.7, t.y - pad * 1.7, t.w + pad * 3.4, t.h + pad * 3.4, pad * 1.2); g.fill(); g.restore();\n  g.fillStyle = '#ffffff'; rrectPath(g, t.x - pad * 0.7, t.y - pad * 0.7, t.w + pad * 1.4, t.h + pad * 1.4, pad * 0.5); g.fill();\n  const ph = await decodeBitmap(photo.file);\n  g.imageSmoothingQuality = 'high'; g.drawImage(ph, t.x, t.y, t.w, t.h);\n  if (ph.close) ph.close();\n  g.font = `${Math.round(pad * 2.6)}px ${FONT}`; g.textAlign = 'center'; g.textBaseline = 'middle';\n  g.fillText(meta.e, t.x - pad * 1.2, t.y - pad * 1.2); g.fillText(meta.e, t.x + t.w + pad * 1.2, t.y + t.h + pad * 1.2);\n  try { setFrame(photo, { blob: await toBlob(c, 'image/jpeg', 0.92), thumb: await canvasThumbBlob(c), w: t.W, h: t.H, kind: 'local', model: 'lokalna' }); }\n  finally { c.width = c.height = 1; }\n}\n\nfunction dropBmp(key) {                                   // usuwa wszystkie warianty rozmiaru danego klucza\n  for (const k of Array.from(bmpCache.keys())) if (k === key || k.startsWith(key + '@')) { const b = bmpCache.get(k); if (b && b.close) b.close(); bmpCache.delete(k); }\n}\nasync function cachedBitmap(key, blob, maxW) {\n  const ck = key + '@' + (maxW || 0);\n  if (bmpCache.has(ck)) { const v = bmpCache.get(ck); bmpCache.delete(ck); bmpCache.set(ck, v); return v; }\n  const bmp = await decodeScaled(blob, maxW);                // podgląd nie potrzebuje pełnej rozdzielczości\n  bmpCache.set(ck, bmp);\n  while (bmpCache.size > 16) { const k0 = bmpCache.keys().next().value, b = bmpCache.get(k0); if (b && b.close) b.close(); bmpCache.delete(k0); }\n  return bmp;\n}\nfunction setFrame(photo, f) {\n  if (photo.frame) { if (photo.frame.url) URL.revokeObjectURL(photo.frame.url); if (photo.frame.thumbUrl) URL.revokeObjectURL(photo.frame.thumbUrl); }\n  dropBmp('f' + photo.id);\n  photo.frame = Object.assign({}, f, { url: URL.createObjectURL(f.blob), thumbUrl: f.thumb ? URL.createObjectURL(f.thumb) : null });\n}\n\nasync function genFrameImage(photo, S, signal) {\n  const p = photo.plan;\n  const prompt = buildFramePrompt(S, p.theme, p.subject, p.pose);\n  const inline = S.frameMode === 'safe'\n    ? { mimeType: 'image/png', data: makeTemplate(photo.ratio, photo.aspect, S.windowPct) }\n    : { mimeType: 'image/jpeg', data: await fileToJpegB64(photo.file, 1024, 0.85) };\n  return genImage({ parts: [{ text: prompt }, { inlineData: inline }], ratio: photo.ratio, size: S.imageSize, S, signal, tag: `Ramka ${photo.n}` });\n}\n\nasync function frameTask(photo, S, signal, tile) {\n  tile.set('run');\n  let done = null, lastErr = null;\n  const tries = S.frameMode === 'safe' ? 3 : 2;\n  for (let a = 1; a <= tries && !done; a++) {\n    try {\n      if (a === 1 && S.useCache !== false) {                    // gotowa ramka z wcześniejszej sesji: zero zapytań\n        const hit = await cacheGet(cacheKey(photo, S));\n        if (hit && hit.blob) {\n          setFrame(photo, { blob: hit.blob, thumb: hit.thumb, w: hit.w, h: hit.h, kind: 'ai', model: hit.model });\n          tile.set('ok', { url: photo.frame.thumbUrl || photo.frame.url, tag: 'z pamięci' });\n          log(`Ramka ${photo.n}: wzięta z pamięci urządzenia (bez zapytania)`);\n          return;\n        }\n      }\n      const Sa = (a > 1 && a === tries) ? Object.assign({}, S, { imageSize: downSize(S.imageSize) }) : S;   // ostatnia próba: niższa rozdzielczość\n      if (Sa !== S && Sa.imageSize !== S.imageSize) log(`Ramka ${photo.n}: ostatnia próba w ${Sa.imageSize}`, 'warn');\n      const gen = await genFrameImage(photo, Sa, signal);\n      const raw = await createImageBitmap(b64ToBlob(gen.b64, gen.mime));\n      try {\n        if (S.frameMode === 'safe') {\n          const det = detectWindow(raw, photo.aspect);\n          if (!det.ok) { lastErr = new Error(det.why); log(`Ramka ${photo.n}: ${det.why} (próba ${a}/${tries})`, 'warn'); continue; }\n          done = await oneAtATime(() => composeSafe(photo, raw, det));\n        } else done = await oneAtATime(() => packFull(raw));\n        done.model = gen.model;\n      } finally { if (raw.close) raw.close(); }\n    } catch (e) {\n      if (e.name === 'AbortError') throw e;\n      lastErr = e; log(`Ramka ${photo.n}: ${e.message}`, 'error');\n      if (e.fatal || e.blocked) break;\n    }\n  }\n  if (done) {\n    setFrame(photo, { blob: done.blob, thumb: done.thumb, w: done.w, h: done.h, kind: 'ai', model: done.model });\n    cachePut(cacheKey(photo, S), { blob: done.blob, thumb: done.thumb, w: done.w, h: done.h, model: done.model });   // zapis w tle\n    tile.set('ok', { url: photo.frame.thumbUrl || photo.frame.url, tag: (IMAGE_MODELS[done.model] || {}).short || done.model, model: done.model });\n  } else {\n    await makeLocalFrame(photo, S);\n    tile.set('err', { url: photo.frame.thumbUrl || photo.frame.url, tag: 'lokalna', msg: lastErr ? lastErr.message : 'błąd' });\n    if (lastErr && lastErr.fatal) throw lastErr;\n  }\n}\n\nasync function stampTask(photo, day, S, signal, tile) {\n  tile.set('run');\n  const theme = String(day.theme).replace(/^\\d+\\.\\s*/, '');\n  const img = await genImage({ parts: [{ text: stampPrompt(photo.timeStr, theme) }], ratio: '1:1', size: '1K', S, signal, tag: `Znacznik ${photo.timeStr}` });\n  const blob = await normalizeToJpeg(img.b64, img.mime, 0.9);\n  if (photo.stamp && photo.stamp.url) URL.revokeObjectURL(photo.stamp.url);\n  dropBmp('s' + photo.id);\n  photo.stamp = { blob, url: URL.createObjectURL(blob), rot: Math.random() > 0.5 ? -4 : 4 };\n  tile.set('ok', { url: photo.stamp.url, tag: photo.timeStr });\n}\n\n/* ===================== 7. OPOWIEŚCI I OKŁADKI ===================== */\nconst STORY_FALLBACK = 'Nie udało się wygenerować opowieści tego dnia. Użyj przycisku „Ponów opowieść dnia” pod tą stroną albo spróbuj za chwilę.';\n\nfunction sampleEvenly(arr, n) {\n  if (arr.length <= n) return arr.slice();\n  const out = [];\n  for (let i = 0; i < n; i++) out.push(arr[Math.round(i * (arr.length - 1) / (n - 1))]);\n  return out;\n}\n// Do opowieści wysyłamy najwyżej 24 zdjęcia z dnia w małym rozmiarze (limit rozmiaru żądania API).\nasync function genStory(day, S, signal) {\n  const sample = sampleEvenly(day.photos, 24);\n  const parts = [{ text: storyPrompt(day, S, sample) }];\n  for (const p of sample) parts.push({ inlineData: { mimeType: 'image/jpeg', data: await fileToJpegB64(p.file, 640, 0.75) } });\n  return genText({ parts, signal, tag: `Opowieść dnia ${day.index}` });\n}\n// Dzieli opowieść na strony po zdaniach; nic nie ginie (nadmiar trafia na ostatnią stronę).\nfunction chunkStory(text, maxPages) {\n  const sentences = text.match(/[^.!?]+[.!?]+[\"”»)]*\\s*/g) || [text];\n  const used = sentences.join('').length;\n  if (used < text.length) sentences.push(text.slice(used));\n  const maxChars = Math.max(550, Math.ceil(text.length / maxPages) + 80);\n  const chunks = []; let cur = '';\n  for (const s of sentences) {\n    if (cur.length + s.length > maxChars && cur.trim()) { chunks.push(cur.trim()); cur = s; } else cur += s;\n  }\n  if (cur.trim()) chunks.push(cur.trim());\n  while (chunks.length > maxPages) { const last = chunks.pop(); chunks[chunks.length - 1] += '\\n' + last; }\n  return chunks.length ? chunks : [text.trim()];\n}\nfunction setCovers(day, texts) {\n  (day.covers || []).forEach(c => { if (c.url) URL.revokeObjectURL(c.url); if (c.thumbUrl) URL.revokeObjectURL(c.thumbUrl); });\n  day.chunks = texts;\n  day.covers = texts.map(t => ({ text: t, blob: null, url: null, model: null }));\n}\nasync function storyTask(day, S, signal, tile) {\n  tile.set('run');\n  try {\n    const raw = await genStory(day, S, signal);\n    day.storyText = formatPolishText(raw);\n    day.storyFailed = false;\n    setCovers(day, chunkStory(day.storyText, S.storyPages));\n    tile.set('ok', { tag: 'opowieść' });\n  } catch (e) {\n    if (e.name === 'AbortError') throw e;\n    day.storyText = ''; day.storyFailed = true;\n    setCovers(day, [STORY_FALLBACK]);\n    tile.set('err', { msg: e.message });\n    throw e;\n  }\n}\nasync function coverTask(day, cv, S, signal, tile) {\n  tile.set('run');\n  const ratio = layoutState.orientation === 'portrait' ? '4:3' : '3:4';\n  const parts = [{ text: coverPrompt(cv.text, S, ratio, !!refImageB64) }];\n  if (refImageB64) parts.push({ inlineData: { mimeType: 'image/jpeg', data: refImageB64 } });\n  const img = await genImage({ parts, ratio, size: S.imageSize, S, signal, tag: `Okładka dnia ${day.index}` });\n  const blob = await normalizeToJpeg(img.b64, img.mime, 0.9);\n  if (cv.url) URL.revokeObjectURL(cv.url);\n  if (cv.thumbUrl) URL.revokeObjectURL(cv.thumbUrl);\n  dropBmp('c' + cv.url);\n  cv.blob = blob; cv.url = URL.createObjectURL(blob); cv.model = img.model;\n  cv.thumbUrl = URL.createObjectURL(await thumbOfBlob(blob));\n  tile.set('ok', { url: cv.thumbUrl, tag: (IMAGE_MODELS[img.model] || {}).short || img.model, model: img.model });\n}\n\n\n/* ===================== 8. UKŁAD I RYSOWANIE STRON ===================== */\n// Miejsce zdjęcia na stronie (jednostki bazowe 1190×1684 / 1684×1190, jak w oryginale).\n// mw/mh = wymiary modułu przed obrotem; rotate = zdjęcie o innej orientacji niż strona obracamy o 90°.\nfunction slotGeom(pageOri, layout, idx, photo) {\n  const P = PAGE[pageOri], portrait = pageOri === 'portrait';\n  if (layout === 'row') {\n    return portrait ? { x: 35 + idx * 570, y: 32, w: 550, h: 1620, rotate: false, mw: 550, mh: 1620 }\n      : { x: 32 + idx * 820, y: 35, w: 800, h: 1120, rotate: false, mw: 800, mh: 1120 };\n  }\n  if (layout === 'col') {\n    return portrait ? { x: 35, y: 32 + idx * 820, w: 1120, h: 800, rotate: false, mw: 1120, mh: 800 }\n      : { x: 32, y: 35 + idx * 585, w: 1620, h: 550, rotate: false, mw: 1620, mh: 550 };\n  }\n  const vw = portrait ? 1120 : 1620, vh = portrait ? 1620 : 1120;\n  const rotate = photo.orientation !== pageOri;\n  return { x: (P.w - vw) / 2, y: (P.h - vh) / 2, w: vw, h: vh, rotate, mw: rotate ? vh : vw, mh: rotate ? vw : vh };\n}\n\nfunction resetResults() {\n  photos.forEach(p => {\n    if (p.frame && p.frame.url) URL.revokeObjectURL(p.frame.url);\n    if (p.frame && p.frame.thumbUrl) URL.revokeObjectURL(p.frame.thumbUrl);\n    if (p.stamp && p.stamp.url) URL.revokeObjectURL(p.stamp.url);\n    dropBmp('f' + p.id); dropBmp('s' + p.id); p.frame = null; p.stamp = null;\n  });\n  days.forEach(d => (d.covers || []).forEach(c => { if (c.url) { URL.revokeObjectURL(c.url); dropBmp('c' + c.url); } if (c.thumbUrl) URL.revokeObjectURL(c.thumbUrl); }));\n  pdfBlob = null;\n}\n\n// Dzieli zdjęcia na dni, układa strony i losuje postać/pozę dla każdego zdjęcia (bez powtórek).\nfunction planLayout(S) {\n  resetResults();\n  layoutState = { orientation: S.orientation, layoutMode: S.layoutMode };\n  const map = new Map();\n  photos.forEach(p => { if (!map.has(p.dateStr)) map.set(p.dateStr, []); map.get(p.dateStr).push(p); });\n  const subjects = new Deck(() => subjectPool(S)), poses = new Deck(() => [...ALL_POSES]);\n  days = []; let di = 1, n = 0;\n  for (const [key, list] of map) {\n    const day = { index: di, key, photos: list, theme: themeForDay(S, di), matrix: [], covers: [], chunks: [], storyText: '', storyFailed: false };\n    let i = 0;\n    while (i < list.length) {\n      const a = list[i], b = list[i + 1];\n      let layout = 'single';\n      if (b && S.layoutMode === 'classic' && a.orientation === 'portrait' && b.orientation === 'portrait') layout = 'row';\n      else if (b && S.layoutMode === 'smart') {\n        if (S.orientation === 'portrait' && a.orientation === 'landscape' && b.orientation === 'landscape') layout = 'col';\n        else if (S.orientation === 'landscape' && a.orientation === 'portrait' && b.orientation === 'portrait') layout = 'row';\n      }\n      const arr = layout === 'single' ? [a] : [a, b];\n      day.matrix.push({ type: 'matrix', day, photos: arr, layout });\n      arr.forEach((p, idx) => { p.slot = slotGeom(S.orientation, layout, idx, p); p.ratio = pickRatio(p.slot.mw / p.slot.mh); });\n      i += arr.length;\n    }\n    list.forEach((p, k) => {\n      p.n = ++n; p.dayIdx = di; p.idxInDay = k;\n      const subject = S.animal === 'random' ? subjects.draw()\n        : S.animal === 'internet' ? 'INTERNET: Wyszukaj obiekt pasujący do: ' + day.theme : S.animal;\n      p.plan = { theme: day.theme, subject, pose: S.pose === 'random' ? poses.draw() : S.pose };\n    });\n    days.push(day); di++;\n  }\n}\nfunction replanPhoto(photo, S) {\n  const day = days.find(d => d.index === photo.dayIdx);\n  let subject = S.animal;\n  if (S.animal === 'random') subject = shuffle(subjectPool(S)).find(x => x !== photo.plan.subject) || photo.plan.subject;\n  else if (S.animal === 'internet') subject = 'INTERNET: Wyszukaj obiekt pasujący do: ' + day.theme;\n  const pose = S.pose === 'random' ? (shuffle([...ALL_POSES]).find(x => x !== photo.plan.pose) || photo.plan.pose) : S.pose;\n  photo.plan = { theme: day.theme, subject, pose };\n}\nconst wantsStamp = (p, S) => S.stampEvery > 0 && !!p.timeStr && p.idxInDay % S.stampEvery === 0;\n\nfunction buildPages(S) {\n  pages = [];\n  days.forEach(day => {\n    if (S.doStory) day.covers.forEach((cv, ci) => pages.push({ type: 'cover', day, cover: cv, chunkIdx: ci }));\n    day.matrix.forEach(pg => pages.push(pg));\n  });\n  pages.forEach((p, i) => { p.no = i + 1; p.total = pages.length; });\n}\n\n/* ---------- rysowanie (Canvas 2D; wszystko w jednostkach bazowych, skala k) ---------- */\n// Cień w canvasie nie skaluje się z transformacją, więc mnożymy go przez k ręcznie.\nfunction shadowOn(g, k, blur, dy, alpha) { g.shadowColor = `rgba(0,0,0,${alpha})`; g.shadowBlur = blur * k; g.shadowOffsetX = 0; g.shadowOffsetY = dy * k; }\nfunction shadowOff(g) { g.shadowColor = 'transparent'; g.shadowBlur = 0; g.shadowOffsetY = 0; }\n\n// Zawijanie tekstu; null = odstęp między akapitami. Nie łamie po niełamliwej spacji.\nfunction wrapLines(g, text, maxW) {\n  const lines = [], paras = text.split(/\\n+/);\n  paras.forEach((para, pi) => {\n    let cur = '';\n    for (const word of para.split(' ')) {\n      const test = cur ? cur + ' ' + word : word;\n      if (cur && g.measureText(test).width > maxW) { lines.push(cur); cur = word; } else cur = test;\n    }\n    lines.push(cur);\n    if (pi < paras.length - 1) lines.push(null);\n  });\n  return lines;\n}\n// Zmniejsza czcionkę tak, aby tekst zawsze mieścił się w ramce (oryginał ucinał końcówki).\nfunction fitText(g, text, maxW, maxH, startPx, minPx, lh) {\n  for (let px = startPx; px >= minPx; px--) {\n    g.font = `600 ${px}px ${FONT}`;\n    const lines = wrapLines(g, text, maxW);\n    if (lines.reduce((s, l) => s + (l === null ? 0.45 : 1), 0) * px * lh <= maxH) return { px, lines };\n  }\n  g.font = `600 ${minPx}px ${FONT}`;\n  return { px: minPx, lines: wrapLines(g, text, maxW) };\n}\nfunction drawTextCard(g, k, text, x, y, w, h, startPx, minPx) {\n  g.save();\n  shadowOn(g, k, 30, 10, 0.07); rrectPath(g, x, y, w, h, 20); g.fillStyle = '#ffffff'; g.fill(); shadowOff(g);\n  const pad = 40, lh = 1.8, fit = fitText(g, text, w - 2 * pad, h - 2 * pad, startPx, minPx, lh);\n  g.font = `600 ${fit.px}px ${FONT}`; g.fillStyle = '#1f2937'; g.textAlign = 'left'; g.textBaseline = 'top';\n  let ty = y + pad;\n  for (const line of fit.lines) { if (line === null) { ty += fit.px * lh * 0.45; continue; } g.fillText(line, x + pad, ty); ty += fit.px * lh; }\n  g.restore();\n}\nasync function drawIllustration(g, k, cv, x, y, w, h, getBmp) {\n  g.save();\n  shadowOn(g, k, 40, 20, 0.16); rrectPath(g, x, y, w, h, 20); g.fillStyle = '#ffffff'; g.fill(); shadowOff(g);\n  g.lineWidth = 5; g.strokeStyle = '#e5e7eb'; rrectPath(g, x + 2.5, y + 2.5, w - 5, h - 5, 18); g.stroke();\n  rrectPath(g, x + 5, y + 5, w - 10, h - 10, 16); g.clip();\n  const bmp = cv.blob ? await getBmp('c' + cv.url, cv.blob, Math.ceil(w * k)) : null;\n  if (bmp) { const r = fitInto(bmp.width, bmp.height, x + 5, y + 5, w - 10, h - 10, 'contain'); g.drawImage(bmp, r.x, r.y, r.w, r.h); }\n  else { g.fillStyle = '#a4b0be'; g.font = `700 24px ${FONT}`; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('Brak ilustracji', x + w / 2, y + h / 2); }\n  g.restore();\n}\nasync function drawCover(g, page, k, ori, getBmp) {\n  const P = PAGE[ori], day = page.day, cv = page.cover;\n  const dateLabel = fmtDate(day.key) + (page.chunkIdx > 0 ? ' (ciąg dalszy)' : '');\n  g.textBaseline = 'top';\n  if (ori === 'portrait') {\n    g.textAlign = 'center';\n    g.fillStyle = '#8b5cf6'; g.font = `800 70px ${FONT}`; g.fillText(`DZIEŃ ${day.index}`, P.w / 2, 80);\n    g.fillStyle = '#6b7280'; g.font = `700 35px ${FONT}`; g.fillText(dateLabel, P.w / 2, 190);\n    await drawIllustration(g, k, cv, 95, 250, 1000, 750, getBmp);\n    drawTextCard(g, k, cv.text, 95, 1050, 1000, 500, 30, 20);\n  } else {\n    g.textAlign = 'left';\n    g.fillStyle = '#8b5cf6'; g.font = `800 80px ${FONT}`; g.fillText(`DZIEŃ ${day.index}`, 80, 80);\n    g.fillStyle = '#6b7280'; g.font = `700 40px ${FONT}`; g.fillText(dateLabel, 80, 190);\n    drawTextCard(g, k, cv.text, 80, 275, 750, 815, 28, 19);\n    await drawIllustration(g, k, cv, 854, 80, 750, 980, getBmp);\n  }\n}\nasync function drawStamp(g, k, photo, r, getBmp) {                     // znacznik godziny: karta w prawym górnym rogu ramki\n  const bmp = await getBmp('s' + photo.id, photo.stamp.blob, Math.ceil(150 * k));\n  g.save();\n  g.translate(r.x + r.w - 40, r.y + 110); g.rotate((photo.stamp.rot || 4) * Math.PI / 180);\n  shadowOn(g, k, 35, 15, 0.25); rrectPath(g, -80, -80, 160, 160, 12); g.fillStyle = '#ffffff'; g.fill(); shadowOff(g);\n  g.lineWidth = 2; g.strokeStyle = '#e5e7eb'; g.stroke();\n  rrectPath(g, -72, -72, 144, 144, 8); g.clip();\n  const c = fitInto(bmp.width, bmp.height, -72, -72, 144, 144, 'cover'); g.drawImage(bmp, c.x, c.y, c.w, c.h);\n  g.restore();\n}\nasync function drawMatrix(g, page, k, ori, getBmp) {\n  for (const photo of page.photos) {\n    const sl = photo.slot;\n    g.save();\n    g.translate(sl.x + sl.w / 2, sl.y + sl.h / 2);\n    if (sl.rotate) g.rotate(-Math.PI / 2);\n    let r = { x: -sl.mw / 2, y: -sl.mh / 2, w: sl.mw, h: sl.mh };\n    const bmp = photo.frame && photo.frame.blob ? await getBmp('f' + photo.id, photo.frame.blob, Math.ceil(sl.mw * k)) : null;\n    if (bmp) { r = fitInto(bmp.width, bmp.height, r.x, r.y, r.w, r.h, 'contain'); g.drawImage(bmp, r.x, r.y, r.w, r.h); }\n    else { g.fillStyle = '#f3f4f6'; g.fillRect(r.x, r.y, r.w, r.h); g.fillStyle = '#a4b0be'; g.font = `800 34px ${FONT}`; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('Brak ramki', 0, 0); }\n    if (photo.stamp && photo.stamp.blob) await drawStamp(g, k, photo, r, getBmp);\n    g.restore();\n  }\n}\nfunction drawPill(g, k, P, text) {\n  g.save();\n  g.font = `800 24px ${FONT}`; g.textAlign = 'center'; g.textBaseline = 'middle';\n  const w = g.measureText(text).width + 50, h = 54, x = (P.w - w) / 2, y = P.h - 30 - h;\n  shadowOn(g, k, 20, 10, 0.3); rrectPath(g, x, y, w, h, 20); g.fillStyle = '#8b5cf6'; g.fill(); shadowOff(g);\n  g.lineWidth = 3; g.strokeStyle = '#ffffff'; g.stroke();\n  g.fillStyle = '#ffffff'; g.fillText(text, P.w / 2, y + h / 2 + 1);\n  g.restore();\n}\nlet fontsReady = null;\nfunction ensureFonts() {\n  if (!fontsReady) fontsReady = (document.fonts && document.fonts.load\n    ? Promise.all(['800 70px Nunito', '700 35px Nunito', '600 30px Nunito'].map(f => document.fonts.load(f, 'ĄĆĘŁŃÓŚŹŻ')))\n    : Promise.resolve()).catch(() => { });\n  return fontsReady;\n}\n// strip = { y0, h } (w pikselach rastra): rysuje tylko wycinek strony. Cała reszta układu jest liczona identycznie,\n// więc sąsiednie paski łączą się bez szwu, a pamięć zależy od wysokości paska, nie od rozmiaru strony.\nasync function renderPage(page, canvas, pxW, getBmp, strip, bleedFrac) {\n  await ensureFonts();\n  const ori = layoutState.orientation, P = PAGE[ori];\n  const bf = bleedFrac || 0, k = pxW * (1 - 2 * bf) / P.w, off = pxW * bf;   // bf: ułamek szerokości zajęty przez spad\n  const fullH = Math.round(P.h * k + 2 * off), y0 = strip ? strip.y0 : 0, h = strip ? strip.h : fullH;\n  canvas.width = Math.round(pxW); canvas.height = h;\n  const g = canvas.getContext('2d');\n  if (!g) throw new Error('przeglądarka odmówiła utworzenia płótna');\n  g.fillStyle = '#ffffff'; g.fillRect(0, 0, canvas.width, canvas.height);\n  g.setTransform(k, 0, 0, k, off, off - y0); g.imageSmoothingEnabled = true; g.imageSmoothingQuality = 'high';\n  if (page.type === 'cover') await drawCover(g, page, k, ori, getBmp); else await drawMatrix(g, page, k, ori, getBmp);\n  drawPill(g, k, P, `Strona ${page.no} z ${page.total}`);\n}\n// Podgląd na ekranie: jedna strona naraz (kolejka), wynik jako mały JPEG.\nlet renderChain = Promise.resolve();\nfunction renderPreview(page, img) {\n  renderChain = renderChain.then(async () => {\n    try {\n      const c = canvasOf(2, 2);\n      await renderPage(page, c, layoutState.orientation === 'portrait' ? 1000 : 1400, (key, blob, maxW) => cachedBitmap(key, blob, maxW));\n      const blob = await toBlob(c, 'image/jpeg', 0.86);\n      c.width = c.height = 1;\n      if (img.dataset.url) URL.revokeObjectURL(img.dataset.url);\n      img.dataset.url = URL.createObjectURL(blob); img.src = img.dataset.url;\n      const ph = img.parentElement.querySelector('.ph'); if (ph) ph.remove();\n    } catch (e) { log(`Podgląd strony ${page.no}: ${e.message}`, 'error'); }\n  });\n  return renderChain;\n}\n\n/* ===================== 9. PDF (własny zapis, bez bibliotek) ===================== */\nconst pf = n => (Math.round(n * 1000) / 1000).toString();\n// items: [{ strips:[{jpeg:Blob, iw, ih, y0, y1}], fullH, pw, ph, x, y, w, h }] – wymiary w punktach (pt), x/y od lewego górnego rogu.\n// Strona może składać się z kilku pasków-obrazów ułożonych jeden pod drugim (dzięki temu nie ma limitu wielkości płótna).\nfunction buildPdf(items) {\n  const enc = new TextEncoder(), parts = [], offs = [];\n  let pos = 0;\n  const push = x => { const b = typeof x === 'string' ? enc.encode(x) : x; parts.push(b); pos += (b.size !== undefined ? b.size : b.length); };\n  push(new Uint8Array([0x25, 0x50, 0x44, 0x46, 0x2D, 0x31, 0x2E, 0x34, 0x0A, 0x25, 0xE2, 0xE3, 0xCF, 0xD3, 0x0A]));\n  let next = 3;\n  items.forEach(it => { it.no = next++; it.ct = next++; it.im = it.strips.map(() => next++); });\n  const obj = (n, body) => { offs[n] = pos; push(`${n} 0 obj\\n${body}\\nendobj\\n`); };\n  obj(1, '<< /Type /Catalog /Pages 2 0 R >>');\n  obj(2, `<< /Type /Pages /Kids [${items.map(it => `${it.no} 0 R`).join(' ')}] /Count ${items.length} >>`);\n  items.forEach(it => {\n    obj(it.no, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pf(it.pw)} ${pf(it.ph)}] /Resources << /XObject << ${it.strips.map((_, j) => `/Im${j} ${it.im[j]} 0 R`).join(' ')} >> >> /Contents ${it.ct} 0 R >>`);\n    let cs = '';\n    it.strips.forEach((st, j) => {                        // pasek zajmuje wiersze [y0, y1) rastra; pozycje liczone z jednej skali, bez kumulacji błędu\n      const top = it.y + st.y0 / it.fullH * it.h, bot = it.y + st.y1 / it.fullH * it.h;\n      cs += `q ${pf(it.w)} 0 0 ${pf(bot - top)} ${pf(it.x)} ${pf(it.ph - bot)} cm /Im${j} Do Q\\n`;\n    });\n    if (it.marks) cs += it.marks;                        // krzyżyki cięcia rysujemy wektorowo, nad obrazem\n    obj(it.ct, `<< /Length ${cs.length} >>\\nstream\\n${cs}endstream`);\n    it.strips.forEach((st, j) => {\n      offs[it.im[j]] = pos;\n      push(`${it.im[j]} 0 obj\\n<< /Type /XObject /Subtype /Image /Width ${st.iw} /Height ${st.ih} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${st.jpeg.size} >>\\nstream\\n`);\n      push(st.jpeg); push('\\nendstream\\nendobj\\n');\n    });\n  });\n  const total = next, xref = pos;\n  let x = `xref\\n0 ${total}\\n0000000000 65535 f \\n`;\n  for (let n = 1; n < total; n++) x += String(offs[n]).padStart(10, '0') + ' 00000 n \\n';\n  push(x + `trailer\\n<< /Size ${total} /Root 1 0 R >>\\nstartxref\\n${xref}\\n%%EOF\\n`);\n  return new Blob(parts, { type: 'application/pdf' });   // Blob z części: przeglądarka trzyma dane na dysku, nie w jednej wielkiej tablicy\n}\n\n/* ---------- eksport w maksymalnej jakości bez zawieszania ---------- */\nconst PDF_MAX_DPI = 600;                  // sufit trybu „Maksymalna” (tyle wystarcza do druku fotograficznego)\nconst STRIP_AREA = 8e6;                   // piksele w jednym pasku strony (~32 MB pamięci na pasek)\nconst STRIP_OVERLAP_PT = 1.5;             // paski zachodzą na siebie o 1,5 pt (liczone w pikselach wg DPI) – przeglądarki PDF nie pokazują szwu\nconst JPEG_Q = 0.95;\nconst BYTES_PER_PX = 0.22;                // zachowawcze oszacowanie rozmiaru JPEG do budżetu pliku\nconst sizeBudget = () => clamp((navigator.deviceMemory || 4) * 150e6, 300e6, 1200e6);\nlet canvasCaps = null;\n// Największa szerokość płótna, jaką przeglądarka faktycznie obsłuży (cienkie płótna – test nic nie kosztuje).\nfunction probeCanvasWidth() {\n  if (canvasCaps) return canvasCaps;\n  let maxW = 4096;\n  for (const w of [32767, 16384, 8192, 4096]) {\n    try {\n      const c = document.createElement('canvas'); c.width = w; c.height = 2;\n      const g = c.getContext('2d'); if (!g) continue;\n      g.fillStyle = '#ff0000'; g.fillRect(w - 2, 0, 2, 2);\n      const ok = g.getImageData(w - 1, 1, 1, 1).data[0] === 255;\n      c.width = c.height = 1;\n      if (ok) { maxW = w; break; }\n    } catch (e) { /* za szerokie */ }\n  }\n  return (canvasCaps = { maxW });\n}\nfunction stripPlan(pxW, pxH) {\n  const area = window.__STRIP_AREA || STRIP_AREA;        // window.__STRIP_AREA: haczyk testowy\n  const maxH = Math.max(256, Math.floor(area / pxW)), n = Math.max(1, Math.ceil(pxH / maxH));\n  return { n, each: Math.ceil(pxH / n) };\n}\nasync function renderStripJpeg(page, pxW, y0, h, getBmp, bleedFrac) {\n  const canvas = document.createElement('canvas');\n  try {\n    await renderPage(page, canvas, pxW, getBmp, { y0, h }, bleedFrac);\n    return await toBlob(canvas, 'image/jpeg', JPEG_Q);\n  } catch (e) {\n    if (e.name === 'AbortError') throw e;\n    const oom = new Error(`nie udało się wyrenderować paska strony (${e.message})`); oom.oom = true; throw oom;\n  } finally { canvas.width = canvas.height = 1; }       // zwalnia pamięć od razu, bez czekania na GC\n}\nlet exportCancelled = false, lastExport = null;\n// Krzyżyki cięcia: cztery narożniki, rysowane poza obszarem spadu, w punktach PDF.\nfunction cropMarkStream(pw, ph, x, y, w, h, bleedPt) {\n  const len = 14, gap = Math.max(2, bleedPt), lw = 0.4;\n  const xs = [x, x + w], ys = [y, y + h];                 // y liczone od dołu strony\n  let cs = `q 0 0 0 RG ${lw} w\\n`;\n  for (const cx of xs) for (const cy of ys) {\n    const dx = cx === x ? -1 : 1, dy = cy === y ? -1 : 1;\n    cs += `${pf(cx + dx * gap)} ${pf(cy)} m ${pf(cx + dx * (gap + len))} ${pf(cy)} l S\\n`;\n    cs += `${pf(cx)} ${pf(cy + dy * gap)} m ${pf(cx)} ${pf(cy + dy * (gap + len))} l S\\n`;\n  }\n  return cs + 'Q\\n';\n}\nasync function buildAlbumPdf(S, dpi, mmW, mmH) {\n  const ori = layoutState.orientation, P = PAGE[ori];\n  const bleed = Math.max(0, Math.min(5, S.bleedMm || 0)), markMm = S.cropMarks ?