/* ---------- konfiguracja Gemini Canvas (przekazywana do każdej aplikacji) ---------- */
var CANVAS=(function(){
  var cfg=null,marker=false;
  try{
    marker=!!document.querySelector('script[data-bard-client-injected],script[ws-interception-config]');
    var needle='{"'+'textModelName"';
    var list=document.querySelectorAll('script');
    for(var k=0;k<list.length&&!cfg;k++){
      var sc=list[k]; if(sc.type==='text/x-pracownia') continue;
      var t=sc.textContent||'',i=t.indexOf(needle); if(i<0) continue;
      try{var d=0;for(var j=i;j<t.length;j++){if(t[j]==='{')d++;else if(t[j]==='}'&&--d===0){cfg=JSON.parse(t.slice(i,j+1));break;}}}catch(e){}
    }
  }catch(e){}
  window.__PRACOWNIA_CFG=cfg;
  return {cfg:cfg,on:!!(cfg||marker)};
})();

/* ---------- mostek wstrzykiwany do każdej aplikacji ---------- */
function bridge(){
  var P=window.parent,H=P&&P.__PRACOWNIA,fe=window.frameElement,id=fe?fe.getAttribute('data-app'):'';
  if(!H) return;
  function send(t,d){try{H.ev(id,t,d);}catch(e){}}
  if(P.__PRACOWNIA_CFG&&!window.__CANVAS_CFG) window.__CANVAS_CFG=P.__PRACOWNIA_CFG;
  try{if(P.storage&&!window.storage) window.storage=P.storage;}catch(e){}
  /* Zapytania do Gemini idą przez stronę główną — tam Canvas podpina konto Gemini (bez klucza). */
  var own=window.fetch;
  window.fetch=function(input,init){
    var url=typeof input==='string'?input:(input&&input.url)||String(input||'');
    if(!/generativelanguage\.googleapis\.com/.test(url)) return own.apply(window,arguments);
    send('req');
    var p;try{p=P.fetch(input,init);}catch(e){send('fail',0);throw e;}
    return Promise.resolve(p).then(function(r){send(r&&r.ok?'ok':'fail',r&&r.status);return r;},
      function(e){send(e&&e.name==='AbortError'?'abort':'fail',0);throw e;});
  };
  /* Zapis plików: zamiast pobierania (które w Gemini bywa zablokowane) plik trafia do okna
     „Gotowe pliki” w pracowni — tam można go pobrać, udostępnić albo wysłać na serwer. */
  function now(){return Date.now();}
  var blobs=new Map(),oURL=URL.createObjectURL,rURL=URL.revokeObjectURL;
  URL.createObjectURL=function(o){var u=oURL.apply(URL,arguments);try{if(o instanceof Blob)blobs.set(u,o);}catch(e){}return u;};
  URL.revokeObjectURL=function(u){blobs.delete(u);return rURL.apply(URL,arguments);};
  var oc=HTMLAnchorElement.prototype.click,od=EventTarget.prototype.dispatchEvent,recent={};
  function grab(a){
    try{
      if(!a||a.tagName!=='A'||!a.hasAttribute('download'))return false;
      var href=a.href||'',name=a.getAttribute('download')||'plik';
      if(!/^(blob|data):/i.test(href))return false;
      if(recent[href]&&now()-recent[href]<1500)return true;recent[href]=now();
      var b=blobs.get(href);
      if(b){send('file',{blob:b,name:name});return true;}
      own(href).then(function(r){return r.blob();}).then(function(bb){send('file',{blob:bb,name:name});},
        function(){try{oc.call(a);}catch(e){}});
      return true;
    }catch(e){return false;}
  }
  HTMLAnchorElement.prototype.click=function(){if(grab(this))return;return oc.apply(this,arguments);};
  EventTarget.prototype.dispatchEvent=function(e){if(e&&e.type==='click'&&this&&this.tagName==='A'&&grab(this))return false;return od.apply(this,arguments);};
  document.addEventListener('click',function(e){var a=e.target&&e.target.closest&&e.target.closest('a[download]');if(a&&e.isTrusted&&grab(a))e.preventDefault();},true);
  var oa=window.alert;window.alert=function(){send('alert');return oa.apply(window,arguments);};
  ['pointerdown','keydown'].forEach(function(t){document.addEventListener(t,function(){send('gesture');},true);});
  /* odczyt pasków postępu aplikacji */
  var seen=typeof WeakMap==='function'?new WeakMap():null,lastSent='x';
  function scan(){
    var val=null,newest=-1;
    try{
      var els=document.querySelectorAll('.bar > i, .prog i, progress');
      for(var k=0;k<els.length;k++){
        var el=els[k];
        if(!el.getClientRects().length) continue;
        var w=el.tagName==='PROGRESS'?(el.max?el.value/el.max*100:NaN):parseFloat(el.style.width);
        if(isNaN(w)) continue;
        var rec=seen&&seen.get(el);
        if(!rec||rec.w!==w){rec={w:w,t:now()};seen&&seen.set(el,rec);}
        if(rec.t>newest){newest=rec.t;val=w;}
      }
      var st=document.getElementById('autoStatus');
      if(st&&st.getClientRects().length){
        var m=/^Automatyczne przetwarzanie paczki: zdjęcie (\d+) z (\d+)/.exec(st.textContent||'');
        if(m) val=(m[1]-1)/m[2]*100;
      }
    }catch(e){}
    var key=val==null?'n':String(Math.round(val*2)/2);
    if(key!==lastSent){lastSent=key;send('bar',val==null?null:Math.max(0,Math.min(100,val)));}
  }
  setInterval(scan,400);
}

/* ---------- dźwięki (Web Audio, bez plików) ---------- */
var soundOn=pref('sound',true),AC=null,master=null,lastStep=0;
function audio(){
  if(!AC){var C=window.AudioContext||window.webkitAudioContext;if(!C)return null;
    try{AC=new C();master=AC.createGain();master.gain.value=.6;master.connect(AC.destination);}catch(e){return null;}}
  if(AC.state==='suspended'){try{AC.resume();}catch(e){}}
  return AC;
}
function tone(f,t,dur,type,vol,to){
  var o=AC.createOscillator(),g=AC.createGain();o.type=type;o.frequency.setValueAtTime(f,t);
  if(to)o.frequency.exponentialRampToValueAtTime(to,t+dur);
  g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
  o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+.05);
}
function hiss(t,dur,vol,freq){
  var n=Math.floor(AC.sampleRate*dur),b=AC.createBuffer(1,n,AC.sampleRate),d=b.getChannelData(0);
  for(var i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);
  var s=AC.createBufferSource(),f=AC.createBiquadFilter(),g=AC.createGain();
  s.buffer=b;f.type='bandpass';f.frequency.value=freq;g.gain.value=vol;s.connect(f);f.connect(g);g.connect(master);s.start(t);
}
var SND={
  start:function(t){tone(392,t,.2,'sine',.45);tone(587,t+.13,.3,'sine',.45);},
  step:function(t,n){var sc=[523,587,659,784,880,1047,1175,1319];tone(sc[((n||1)-1)%8],t,.16,'triangle',.32);},
  save:function(t){hiss(t,.08,.9,2600);tone(1568,t+.07,.4,'sine',.26);tone(2093,t+.12,.45,'sine',.16);},
  done:function(t){[523,659,784,1047].forEach(function(f,i){tone(f,t+i*.11,i===3?.8:.24,'triangle',.42);});tone(1568,t+.44,.8,'sine',.14);},
  warn:function(t){tone(660,t,.16,'square',.1);tone(523,t+.18,.24,'square',.1);},
  error:function(t){tone(220,t,.36,'sawtooth',.16,140);tone(165,t+.2,.42,'sawtooth',.13,110);}
};
var sndLog=[];
function snd(k,n){
  sndLog.push(k);if(sndLog.length>30)sndLog.shift();
  if(!soundOn)return;if(k==='step'){if(now()-lastStep<130)return;lastStep=now();}
  var a=audio();if(!a)return;try{SND[k](a.currentTime+.03,n);}catch(e){}
}

/* ---------- blokada uśpienia ekranu ---------- */
var wakeWant=pref('wake',true),wl=null,wakeMode='';
var vid=$('#nosleep');
function wakeOn(){
  if(!wakeWant||document.visibilityState!=='visible')return;
  if(wl){render();return;}
  var fallback=function(){try{var p=vid.play();if(p&&p.then)p.then(function(){wakeMode='video';render();},function(){render();});}catch(e){}};
  if(navigator.wakeLock&&navigator.wakeLock.request){
    navigator.wakeLock.request('screen').then(function(l){
      wl=l;wakeMode='api';try{vid.pause();}catch(e){}
      l.addEventListener('release',function(){wl=null;wakeMode='';render();if(document.visibilityState==='visible')setTimeout(wakeOn,300);});render();
    },fallback);
  }else fallback();
}
function wakeOff(){try{if(wl)wl.release();}catch(e){}wl=null;try{vid.pause();}catch(e){}wakeMode='';render();}
vid.addEventListener('timeupdate',function(){if(vid.currentTime>2.5)vid.currentTime=.5;});
document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')wakeOn();});

